<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {http,dataOf} from '../api/http'
import {useAuthStore} from '../stores/auth'
const auth=useAuthStore(),router=useRouter(),profile=ref<any|null>(null),myShares=ref<any[]>([]),saving=ref(false),changing=ref(false),changingSecondary=ref(false)
const form=reactive({realName:'',email:'',phone:''}),password=reactive({currentPassword:'',newPassword:'',confirmPassword:''}),secondary=reactive({currentPassword:'',currentSecondaryPassword:'',newSecondaryPassword:'',confirmSecondaryPassword:''})
async function load(){const [profileResponse,shareResponse]=await Promise.all([http.get('/user/profile'),http.get('/shares/mine')]);profile.value=dataOf(profileResponse);myShares.value=dataOf(shareResponse);Object.assign(form,{realName:profile.value.realName,email:profile.value.email||'',phone:profile.value.phone||''})}
async function save(){saving.value=true;try{await http.put('/user/profile',{realName:form.realName,email:form.email||null,phone:form.phone||null});auth.updateProfile(form.realName);ElMessage.success('个人资料已更新');await load()}finally{saving.value=false}}
async function changePassword(){if(password.newPassword!==password.confirmPassword)return ElMessage.warning('两次输入的新密码不一致');changing.value=true;try{await http.put('/user/password',password);auth.clearSession();ElMessage.success('密码已修改，请重新登录');router.replace('/login')}finally{changing.value=false}}
async function changeSecondaryPassword(){if(secondary.newSecondaryPassword!==secondary.confirmSecondaryPassword)return ElMessage.warning('两次输入的新二级密码不一致');changingSecondary.value=true;try{await http.put('/user/secondary-password',{currentPassword:profile.value.secondaryPasswordSet?null:secondary.currentPassword,currentSecondaryPassword:profile.value.secondaryPasswordSet?secondary.currentSecondaryPassword:null,newSecondaryPassword:secondary.newSecondaryPassword,confirmSecondaryPassword:secondary.confirmSecondaryPassword});ElMessage.success(profile.value.secondaryPasswordSet?'二级密码已修改':'二级密码已设置');Object.assign(secondary,{currentPassword:'',currentSecondaryPassword:'',newSecondaryPassword:'',confirmSecondaryPassword:''});await load()}finally{changingSecondary.value=false}}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h1 class="page-title">个人中心</h1><div class="page-subtitle">维护个人资料、查看直接授权与选择性共享范围并安全修改密码</div></div></div><div class="profile-grid" v-if="profile"><section class="surface profile-card"><div class="identity"><div class="avatar">{{profile.realName.slice(0,1)}}</div><div><h2>{{profile.realName}}</h2><p class="mono">{{profile.username}}</p></div></div><el-descriptions :column="1" border><el-descriptions-item label="部门">{{profile.department||'未分配'}}</el-descriptions-item><el-descriptions-item label="角色"><el-tag v-for="role in profile.roles" :key="role" size="small">{{role}}</el-tag></el-descriptions-item><el-descriptions-item label="直接数据域">{{profile.assignedScopes?.join(', ')||'未分配'}}</el-descriptions-item><el-descriptions-item label="有效读取域">{{profile.dataScopes.join(', ')||'未分配'}}</el-descriptions-item><el-descriptions-item label="二级密码"><el-tag :type="profile.secondaryPasswordSet?'success':'warning'">{{profile.secondaryPasswordSet?'已设置':'未设置'}}</el-tag></el-descriptions-item><el-descriptions-item label="最近登录">{{profile.lastLoginTime||'—'}}</el-descriptions-item><el-descriptions-item label="创建时间">{{profile.createdTime}}</el-descriptions-item></el-descriptions><div class="share-list"><h3>当前收到的共享</h3><el-empty v-if="!myShares.length" description="暂无选择性共享" :image-size="50"/><article v-for="rule in myShares" :key="rule.id"><b>{{rule.resourceName}}</b><span>{{rule.operations.join(' / ')}} · {{rule.validTo||'长期有效'}}</span></article></div></section><section class="surface form-card"><el-tabs><el-tab-pane label="个人资料"><el-form label-position="top"><el-form-item label="真实姓名"><el-input v-model="form.realName"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" type="email"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone" maxlength="11"/></el-form-item><el-button type="primary" :loading="saving" @click="save">保存资料</el-button></el-form></el-tab-pane><el-tab-pane label="修改密码"><el-alert title="修改成功后，所有现有会话会被撤销，需要重新登录。" type="warning" :closable="false"/><el-form label-position="top" style="margin-top:18px"><el-form-item label="当前密码"><el-input v-model="password.currentPassword" type="password" show-password/></el-form-item><el-form-item label="新密码"><el-input v-model="password.newPassword" type="password" show-password/></el-form-item><el-form-item label="确认新密码"><el-input v-model="password.confirmPassword" type="password" show-password/></el-form-item><el-button type="primary" :loading="changing" @click="changePassword">修改密码并退出</el-button></el-form></el-tab-pane><el-tab-pane label="二级密码"><el-alert title="6位二级密码用于审核、发布等电子签名操作，请勿与登录密码或常用PIN相同；连续失败5次会锁定30分钟。" type="info" :closable="false"/><el-form label-position="top" style="margin-top:18px"><el-form-item v-if="!profile.secondaryPasswordSet" label="当前登录密码"><el-input v-model="secondary.currentPassword" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item v-else label="当前二级密码"><el-input v-model="secondary.currentSecondaryPassword" type="password" maxlength="6" show-password/></el-form-item><el-form-item label="新二级密码"><el-input v-model="secondary.newSecondaryPassword" type="password" maxlength="6" show-password/></el-form-item><el-form-item label="确认二级密码"><el-input v-model="secondary.confirmSecondaryPassword" type="password" maxlength="6" show-password/></el-form-item><el-button type="primary" :loading="changingSecondary" :disabled="(!profile.secondaryPasswordSet&&!secondary.currentPassword)||(profile.secondaryPasswordSet&&!/^[0-9]{6}$/.test(secondary.currentSecondaryPassword))||!/^[0-9]{6}$/.test(secondary.newSecondaryPassword)||secondary.newSecondaryPassword!==secondary.confirmSecondaryPassword" @click="changeSecondaryPassword">{{profile.secondaryPasswordSet?'修改二级密码':'设置二级密码'}}</el-button></el-form></el-tab-pane></el-tabs></section></div></div></template>
<style scoped>.profile-grid{display:grid;grid-template-columns:380px 1fr;gap:16px}.profile-card,.form-card{padding:24px}.identity{display:flex;align-items:center;gap:15px;margin-bottom:22px}.avatar{width:58px;height:58px;border-radius:16px;background:linear-gradient(135deg,#216b9b,#5bb9ba);color:#fff;display:grid;place-items:center;font-size:25px;font-weight:800}.identity h2{margin:0;font-size:20px}.identity p{margin:5px 0 0;color:#7f8da0;font-size:11px}.el-tag+.el-tag{margin-left:5px}.form-card :deep(.el-form){max-width:560px}.share-list{margin-top:20px}.share-list h3{font-size:13px}.share-list article{padding:10px 0;border-top:1px solid #edf1f5}.share-list b,.share-list span{display:block}.share-list span{font-size:10px;color:#8492a4;margin-top:4px}@media(max-width:780px){.profile-grid{grid-template-columns:1fr}}</style>
